#!/usr/bin/env bun
// Build frontend/osa-runtime.bundle.js and write its integrity hash into the widget.
//
//   bun scripts/build-runtime-bundle.js           rebuild both files
//   bun scripts/build-runtime-bundle.js --check   fail if either is stale (CI)
//
// WHY THE RUNTIME IS A SEPARATE, HASHED FILE
//
// The widget is one classic script, and the versioned embed pins it by SRI.
// The runtime is about 60 KB minified and most pages that embed the widget never
// run code, so it is loaded lazily, only for a community that configures client
// tools. Loading it as a plain second file would leave an SRI-pinned embed
// running code nothing verified. So the widget carries this file's sha384 and
// injects it with an integrity attribute: the browser refuses a runtime that
// does not match before any of it runs, which extends the embedder's pin to it.
//
// WHY THE BUILD IS PINNED
//
// --check rebuilds and compares bytes. That is only meaningful if every machine
// produces the same bytes from the same sources, so the Bun that builds is the
// one named in package.json's packageManager field, which CI installs too. A
// different Bun can minify differently and would fail the check for a reason
// that has nothing to do with the sources.
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const ROOT = resolve(import.meta.dir, '..');
const ENTRY = resolve(ROOT, 'frontend/osa-runtime-entry.js');
const BUNDLE = resolve(ROOT, 'frontend/osa-runtime.bundle.js');
const WIDGET = resolve(ROOT, 'frontend/osa-chat-widget.js');
const MARKED = /(\/\/ BEGIN GENERATED: runtime bundle integrity\n\s*const RUNTIME_BUNDLE_INTEGRITY = ')[^']*(';\n\s*\/\/ END GENERATED: runtime bundle integrity)/;

const check = process.argv.includes('--check');

const pinned = JSON.parse(readFileSync(resolve(ROOT, 'package.json'), 'utf8')).packageManager;
const expected = typeof pinned === 'string' ? pinned.replace(/^bun@/, '') : null;
if (expected !== Bun.version) {
  console.error(
    `This bundle must be built with Bun ${expected} (package.json packageManager), and this is ${Bun.version}. ` +
      'A different Bun can minify differently, which would change the bundle and its hash.'
  );
  process.exit(1);
}

const result = await Bun.build({
  entrypoints: [ENTRY],
  minify: true,
  format: 'iife',
  target: 'browser',
});
if (!result.success) {
  for (const message of result.logs) console.error(message);
  process.exit(1);
}
const bundle = `// Generated by scripts/build-runtime-bundle.js from frontend/osa-runtime-entry.js. Do not edit.\n${await result.outputs[0].text()}`;
const integrity = `sha384-${createHash('sha384').update(bundle).digest('base64')}`;

const widget = readFileSync(WIDGET, 'utf8');
if (!MARKED.test(widget)) {
  console.error(`The integrity markers are missing from ${WIDGET}.`);
  process.exit(1);
}
const updatedWidget = widget.replace(MARKED, `$1${integrity}$2`);

if (check) {
  let current = '';
  try {
    current = readFileSync(BUNDLE, 'utf8');
  } catch {
    // Missing counts as stale.
  }
  const stale = [];
  if (current !== bundle) stale.push('frontend/osa-runtime.bundle.js');
  if (updatedWidget !== widget) stale.push('the integrity line in frontend/osa-chat-widget.js');
  if (stale.length > 0) {
    console.error(`Stale: ${stale.join(' and ')}. Run: bun scripts/build-runtime-bundle.js`);
    process.exit(1);
  }
  console.log(`Runtime bundle is current (${bundle.length} bytes, ${integrity}).`);
} else {
  writeFileSync(BUNDLE, bundle);
  writeFileSync(WIDGET, updatedWidget);
  console.log(`Wrote frontend/osa-runtime.bundle.js (${bundle.length} bytes) and ${integrity} into the widget.`);
}
